    /// <summary>Finds the descriptor of one schema identifier.</summary>
    /// <param name="identifier">The schema identifier to look up.</param>
    /// <param name="descriptor">Receives the descriptor when one is described.</param>
    /// <returns><see langword="true"/> when the identifier is described.</returns>
    public static bool TryGetSchema(
        string identifier,
        out OpenUsdPhysicsSchemaDescriptor? descriptor)
    {
        ArgumentNullException.ThrowIfNull(identifier);
        for (int index = 0; index < Schemas.Count; index++)
        {
            if (string.Equals(Schemas[index].Identifier, identifier, StringComparison.Ordinal))
            {
                descriptor = Schemas[index];
                return true;
            }
        }

        descriptor = null;
        return false;
    }

    /// <summary>Finds the descriptor of one namespaced property name.</summary>
    /// <param name="name">The namespaced property name.</param>
    /// <param name="descriptor">Receives the descriptor when one is described.</param>
    /// <returns><see langword="true"/> when the property is described.</returns>
    public static bool TryGetProperty(
        string name,
        out OpenUsdPhysicsPropertyDescriptor? descriptor)
    {
        ArgumentNullException.ThrowIfNull(name);
        for (int index = 0; index < Schemas.Count; index++)
        {
            IReadOnlyList<OpenUsdPhysicsPropertyDescriptor> properties = Schemas[index].Properties;
            for (int property = 0; property < properties.Count; property++)
            {
                if (string.Equals(properties[property].Name, name, StringComparison.Ordinal))
                {
                    descriptor = properties[property];
                    return true;
                }
            }
        }

        descriptor = null;
        return false;
    }
